actions.script:
import org.moqui.adk.AdkManager
import org.moqui.adk.AdkSessionHolder

// Lazy-init ADK runner from saved config if not yet started
if (!AdkManager.isInitialized()) {
    boolean wasDisabled = ec.artifactExecution.disableAuthz()
    def cfg
    try { cfg = ec.entity.find('moqui.adk.AdkAgentConfig').condition('enabled','Y').one() }
    finally { if (!wasDisabled) ec.artifactExecution.enableAuthz() }

    if (cfg) {
        AdkManager.init(cfg.agentName, cfg.modelName, cfg.instruction, cfg.apiKey)
    } else {
        String envKey = System.getenv('GOOGLE_API_KEY') ?:
                        System.getenv('GOOGLE_GENAI_API_KEY') ?:
                        System.getenv('GEMINI_API_KEY') ?: ''
        if (envKey) AdkManager.init(null, 'gemini-2.0-flash', '', envKey)
    }
}

if (!AdkManager.isInitialized()) {
    ec.message.addError('ADK not configured — add API key in ADK → Configuration')
    return
}

def adkSession = AdkManager.createSession(ec.user.userId ?: 'anonymous')
sessionId = adkSession.id as String
// Mirror in AdkSessionHolder so the ChatUI inspector panel keeps working
AdkSessionHolder.sessions[sessionId] = []
AdkSessionHolder.logEvent(sessionId, 'session_created', 'Session created', [sessionId: sessionId])

import org.moqui.adk.AdkManager
import org.moqui.adk.AdkSessionHolder

// Lazy-init ADK runner from saved config if not yet started
if (!AdkManager.isInitialized()) {
    boolean wasDisabled = ec.artifactExecution.disableAuthz()
    def cfg
    try { cfg = ec.entity.find('moqui.adk.AdkAgentConfig').condition('enabled','Y').one() }
    finally { if (!wasDisabled) ec.artifactExecution.enableAuthz() }

    if (cfg) {
        AdkManager.init(cfg.agentName, cfg.modelName, cfg.instruction, cfg.apiKey)
    } else {
        String envKey = System.getenv('GOOGLE_API_KEY') ?:
                        System.getenv('GOOGLE_GENAI_API_KEY') ?:
                        System.getenv('GEMINI_API_KEY') ?: ''
        if (envKey) AdkManager.init(null, 'gemini-2.0-flash', '', envKey)
    }
}

if (!AdkManager.isInitialized()) {
    response = '[Error: ADK not configured — add API key in ADK → Configuration]'
    return
}

AdkSessionHolder.logEvent(sessionId, 'user_message', 'User message', [message: message])

def events = AdkManager.runAgent(ec.user.userId ?: 'anonymous', sessionId, message)
def textEvent = events.reverse().find { it.content?.parts }
response = textEvent?.content?.parts?.find { it.text }?.text ?: ''

if (!response) response = '[No response from agent]'
AdkSessionHolder.logEvent(sessionId, 'agent_response', 'Agent replied', [response: response])
